using System.Collections.Generic;

namespace DurangoServer.Core;

// ข้อมูลรอบ ๆ สูตรคราฟต์ (generated จาก data/assets/item/recipes.json — ข้อมูลชุดเดียวกับ client ที่ผู้เล่นใช้)
// สร้างด้วย scripts/extract_recipe_meta.py — อย่าแก้มือ
//
// ช่องวัตถุดิบอยู่ที่ RecipeRequirements.cs — ไฟล์นี้คือส่วนที่เหลือ:
// เวลา/สตามินา/จำนวนที่ได้/โต๊ะที่ต้องใช้/เครื่องมือที่ต้องถือ/ผลลัพธ์ที่เปลี่ยนตามวัตถุดิบ
public static class RecipeMeta
{
    /// <summary>เงื่อนไขข้อเดียวของผลลัพธ์ — "ช่อง main มีของที่ติด tag meat มากกว่า 0 ชิ้น"</summary>
    public sealed class Criterion
    {
        public readonly string SlotId;
        public readonly string TagId;
        /// <summary>"&gt;0" (ต้องมี) หรือ "&lt;0" (ต้องไม่มี) — ข้อมูลเกมมีแค่สองแบบนี้</summary>
        public readonly string Condition;
        public Criterion(string slotId, string tagId, string condition)
        {
            SlotId = slotId; TagId = tagId; Condition = condition;
        }
    }

    /// <summary>ผลลัพธ์ทางเลือกหนึ่งอัน — เข้าเงื่อนไขครบทุกข้อถึงจะได้ prototype นี้</summary>
    public sealed class Output
    {
        public readonly string PrototypeId;
        public readonly Criterion[] Criteria;
        public Output(string prototypeId, Criterion[] criteria)
        {
            PrototypeId = prototypeId; Criteria = criteria;
        }
    }

    public sealed class Tag
    {
        public readonly string Id;
        public readonly int Level;
        public Tag(string id, int level) { Id = id; Level = level; }
    }

    public sealed class Info
    {
        public readonly string Category;
        public readonly string Subcategory;
        /// <summary>วินาทีที่ใช้คราฟต์ (ก่อนคูณสกิล)</summary>
        public readonly float Duration;
        /// <summary>สตามินาที่เสีย</summary>
        public readonly float Energy;
        /// <summary>คราฟต์ครั้งเดียวได้กี่ชิ้น</summary>
        public readonly int Count;
        public readonly int MinLevel;
        /// <summary>0 = Craft (ได้ของใหม่) · 1 = Modify (แปรรูปของเดิม เช่น ย่าง/ต้ม) · 2 = Reform (แก้ทรงเสื้อ)</summary>
        public readonly int Type;
        /// <summary>prototype ตั้งต้นของผลลัพธ์ (ก่อนดู Outputs)</summary>
        public readonly string PrototypeId;
        /// <summary>ต้องมีโต๊ะ/เตาที่ติด tag ใด tag หนึ่งในนี้ (null = ไม่ต้องใช้โต๊ะ)</summary>
        public readonly Tag[] Workbench;
        /// <summary>ต้องถือเครื่องมือที่ติด tag ใด tag หนึ่งในนี้ (bare_hands = มือเปล่าก็ได้)</summary>
        public readonly Tag[] Tools;
        public readonly Output[] Outputs;

        public Info(string category, string subcategory, float duration, float energy, int count,
            int minLevel, int type, string prototypeId, Tag[] workbench, Tag[] tools, Output[] outputs)
        {
            Category = category; Subcategory = subcategory; Duration = duration; Energy = energy;
            Count = count; MinLevel = minLevel; Type = type; PrototypeId = prototypeId;
            Workbench = workbench; Tools = tools; Outputs = outputs;
        }
    }

    private static Tag T(string id, int level) => new Tag(id, level);
    private static Criterion C(string slot, string tag, string cond) => new Criterion(slot, tag, cond);
    private static Output O(string proto, Criterion[] crit) => new Output(proto, crit);

    private static Info I(string cat, string sub, float dur, float energy, int count,
        int minLevel, int type, string proto, Tag[] wb, Tag[] tools, Output[] outputs)
        => new Info(cat, sub, dur, energy, count, minLevel, type, proto, wb, tools, outputs);

